      <div className="box-border absolute left-[40px] top-[50px] w-[20px] shrink-0 h-[10px] bg-[color:#c43d27]" />
      <div className="box-border absolute left-[100.5px] top-[20.25px] w-[30px] shrink-0 h-[30px] rotate-[30deg] bg-[color:#1e2336] rounded-[50%]" />
      <div className="box-border absolute left-[10px] top-[200px] w-max h-max text-[color:#1e2336] font-[family-name:Inter,_system-ui,_sans-serif] text-[length:16px] font-[400] leading-[1.4] text-left whitespace-pre-wrap [overflow-wrap:anywhere] m-0">Livre</div>
      <svg className="box-border absolute left-[200px] top-[100px] w-[80px] shrink-0 h-[9px] overflow-visible block">
        <path d="M0 0 C 20 -30 60 30 80 0" fill="none" fillRule="nonzero" strokeLinecap="round" strokeLinejoin="round" stroke="#c43d27" strokeWidth={3} />
      </svg>
      <div className="box-border absolute left-[31.23px] top-[5.63px] w-[14.14px] shrink-0 h-[14.14px]">
        <div className="box-border absolute left-[2.07px] top-[2.07px] w-[10px] shrink-0 h-[10px] rotate-[45deg]" />
      </div>
    </div>
  );
}

