{"component":"import styles from "./Board.module.css";

export function Board() {
  return (
    <div data-name="Board" className={styles.board}>
      <div className={styles.r1} />
      <div className={styles.e1} />
      <div className={styles.t1}>Livre</div>
      <svg className={styles.p1}>
        <path d="M0 0 C 20 -30 60 30 80 0" fill="none" fillRule="nonzero" strokeLinecap="round" strokeLinejoin="round" stroke="#c43d27" strokeWidth={3} />
      </svg>
      <div data-name="Botão" className={styles.botao}>
        <div className={styles.lbl}>Salvar</div>
        <svg className={styles.ico}>
          <path d="M0 0 L8 8 M8 0 L0 8" fill="none" fillRule="nonzero" strokeLinecap="round" strokeLinejoin="round" stroke="#ffffff" strokeWidth={1} />
        </svg>
      </div>
      <div className={styles.badge}>
        <div className={styles.bg}>
          <div className={styles.dot} />
          <div className={styles.bar} />
        </div>
      </div>
      <div data-name="Enviar" className={styles.enviar}>
        <div className={styles.i10bzyiqi0vw20y4}>Salvar</div>
        <svg className={styles.i11qrxohh1a842nx}>
          <path d="M0 0 L8 8 M8 0 L0 8" fill="none" fillRule="nonzero" strokeLinecap="round" strokeLinejoin="round" stroke="#ffffff" strokeWidth={1} />
        </svg>
      </div>
      <div className={styles.i2}>
        <div className={styles.i20ov6n7z0wq0u11}>Cancelar</div>
        <svg className={styles.i218kyngc19e59l0} viewBox="0 0 8 8" preserveAspectRatio="xMidYMid meet">
          <path d="M0 0 L8 8 M8 0 L0 8" fill="none" fillRule="nonzero" strokeLinecap="round" strokeLinejoin="round" stroke="#ffffff" strokeWidth={1.5} />
        </svg>
      </div>
      <div className={styles.i3}>
        <div className={styles.i313wdmqh00odcjz}>
          <div className={styles.i319usgs517w2zul} />
          <div className={styles.i314mqdmf18d88r7} />
        </div>
      </div>
    </div>
  );
}
